 "initial_node": "setup",
 "system_prompt": "You are the digital assistant of Freya Bank, calling a customer. Speak Turkish only, one or two short sentences per turn, and address the customer as {{addr}}. Before identity is verified, never say 'tahsilat', 'borç', 'ödeme', the product or the reason for the call, to anyone, relatives included. Never invent amounts, dates, figures, reasons or terms: use only the facts you are given; if you do not have some information, say 'Bu bilgiye sahip değilim.' Never offer a discount, waiver, instalment plan or any term the bank did not give you. Never ask 'ne kadar ödeyebilirsiniz?'. Never say a promise is recorded unless a tool said so. A recorded promise cannot be changed or cancelled in this call; the customer can change it in the mobile app. After every tool result, either speak to the customer or call the next tool: never end a turn with nothing. Call one tool per message. Follow what_to_do_next in a tool result.",
 "test_variables": {
  "customer_id": "c_4f2a91",
  "customerNumber": "c_4f2a91",
  "first_name": "Daniel",
  "last_name": "Reyes",
  "title": "Mr",
  "now": "2026-10-14T11:00"
 },
 "nodes": {
  "setup": {
   "name": "setup", "node_type": "code", "passthrough": true, "passthrough_default_transition": "opening",
   "on_enter": {"type": "silent"}, "disable_inactivity_monitor": true,
   "pre_actions": [{"type": "function", "function": {"name": "code_exec", "handler": "__function__:code_exec", "parameters": {"type": "object", "properties": {"code": {"type": "string", "default": "import datetime

HOL = ['2026-10-26', '2026-11-11', '2026-11-26', '2026-12-25', '2027-01-01']
GUN = ['Pazartesi', 'Salı', 'Çarşamba', 'Perşembe', 'Cuma', 'Cumartesi', 'Pazar']
AY = ['Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']

def parse_now(value):
    s = str(value or '').strip().replace(' ', 'T').rstrip('Z')
    for fmt, size in (('%Y-%m-%dT%H:%M:%S', 19), ('%Y-%m-%dT%H:%M', 16), ('%Y-%m-%d', 10)):
        try:
            return datetime.datetime.strptime(s[:size], fmt)
        except ValueError:
            pass
    raise ValueError('now')

def is_bd(d, hol):
    return d.weekday() < 5 and d not in hol

def next_bd(d, hol):
    d = d + datetime.timedelta(days=1)
    while not is_bd(d, hol):
        d = d + datetime.timedelta(days=1)
    return d

def spoken(d):
    return str(d.day) + ' ' + AY[d.month - 1] + ' ' + str(d.year) + ' ' + GUN[d.weekday()]

try:
    now = parse_now(vars.get('now'))
    hol = set(datetime.date.fromisoformat(h) for h in HOL)
    today = now.date()
    nb = next_bd(today, hol)
    parts = []
    if is_bd(today, hol) and now.hour < 18:
        start = max(now.strftime('%H:%M'), '10:00')
        parts.append('bugün (' + spoken(today) + ') saat ' + start + ' sonrasından 18:00 dahil saate kadar')
    parts.append(spoken(nb) + ' günü 10:00 ile 18:00 arasında (ikisi dahil)')
    vars['cb_window_text'] = 'Geri arama yalnızca ' + ' veya '.join(parts) + ' olabilir. Bugün ' + spoken(today) + ', saat ' + now.strftime('%H:%M') + '.'
except Exception:
    vars['cb_window_text'] = 'Geri arama yalnızca bugün veya sonraki iş günü 10:00 ile 18:00 arasında olabilir.'
t = str(vars.get('title') or '').strip().lower()
vars['addr'] = ('Bay' if t in ('mr', 'mr.', 'bay') else 'Bayan' if t in ('ms', 'ms.', 'mrs', 'bayan') else str(vars.get('title') or '')) + ' ' + str(vars.get('last_name') or '')
vars['close_outcome'] = 'not_reached'
vars['close_reason'] = 'unclear'
vars['cb_tries'] = '0'
vars['id_state'] = 'pending'
vars['call_state'] = 'open'
vars['id_declines'] = '0'
"}, "timeout_ms": {"type": "number", "default": 10000}}}}}],
   "transitions": [{"target_node": "opening", "description": "always", "condition": {"operator": "always"}}]
  },
  "opening": {
   "name": "opening", "node_type": "conversation",
   "on_enter": {"type": "tts", "text": "Merhaba, ben Freya Bank'tan arayan bir dijital asistanım ve görüşmeniz kaydediliyor. {{addr}} ile mi görüşüyorum?"},
   "on_enter_first_entry_only": true,
   "task_message": "Find out whether you are speaking with {{addr}}. Only 'evet', 'benim', 'dinliyorum' or the customer's own name confirms it; 'alo', 'buyurun' and 'kim arıyor' do not: then ask once more '{{addr}} ile mi görüşüyorum?'. If they ask a question, answer it first, then ask. Say nothing about why you are calling. Call end_call only right after you said goodbye.",
   "tools": [{"type": "function", "config": {"timeoutMs": 10000}, "function": {"name": "end_call", "handler": "__function__:end_call", "description": "Ends the call. CALL it right after you said goodbye, with no other text.", "parameters": {"type": "object", "properties": {"message_mode": {"type": "string", "default": "none"}}}}}],
   "extraction_schema": [{"name": "who", "type": "string", "enum_values": ["stay", "customer", "someone_else", "not_their_line", "deceased", "unclear_again"], "description": "customer: a clear 'evet', 'benim', 'dinliyorum' or their own name. someone_else: another person answered. not_their_line: the number is not the customer's. deceased: the customer has died. unclear_again: the agent already asked twice whether it speaks with the customer and the latest answer is still no confirmation. Else stay.", "min_confidence": 0.6}],
   "max_node_turns": 4, "max_turn_transition": "goodbye_short",
   "transitions": [
    {"target_node": "identity", "description": "Customer confirmed", "condition": {"logic": "or", "conditions": [{"variable": "who", "operator": "equals", "operand": "customer"}]}},
    {"target_node": "mark_deceased", "description": "Deceased", "condition": {"logic": "or", "conditions": [{"variable": "who", "operator": "equals", "operand": "deceased"}]}},
    {"target_node": "third_party_prep", "description": "Someone else", "condition": {"logic": "or", "conditions": [{"variable": "who", "operator": "equals", "operand": "someone_else"}]}},
    {"target_node": "mark_wrong_number", "description": "Wrong number", "condition": {"logic": "or", "conditions": [{"variable": "who", "operator": "equals", "operand": "not_their_line"}]}},
    {"target_node": "goodbye_short", "description": "Still unclear after the second ask", "condition": {"logic": "or", "conditions": [{"variable": "who", "operator": "equals", "operand": "unclear_again"}]}}
   ]
  },
  "mark_deceased": {
