    if reply == 'vague':
        if not st['vague_asked']:
            st['vague_asked'] = True
            out['say'] = 'Hangi gün ödeyebileceğinizi kesin olarak söyleyebilir misiniz?'
        else:
            st['date'] = deadline.isoformat()
            st['phase'] = 'ask'
            out['say'] = 'O zaman son tarihiniz olan ' + spoken(deadline) + ' tarihinde ' + money(st['amount']) + ' ödeyebilir misiniz?'
    elif reply == 'too_much':
        if st['floor_offered']:
